from collections import deque
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14
    AAPL_BUY_CASH = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.SetWarmUp(self.SMA_PERIOD, Resolution.Daily)

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_close = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = None
        self.aapl_previous_rsi = None
        self.rsi_change_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.last_processed_date = None

    def OnData(self, data):
        current_date = self.Time.date()

        if self.last_processed_date == current_date:
            return

        self.last_processed_date = current_date

        bars = {}
        for symbol in self.all_symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        if self.spy in bars:
            self._update_spy_state(float(bars[self.spy].Close))

        if self.aapl in bars:
            self._update_aapl_state(float(bars[self.aapl].Close))

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.all_symbols):
            return

        if self.strategy_a_lot > 0 and self.spy_crossed_below:
            self._sell_strategy_a()

        if self.strategy_b_lot > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60.0:
            self._sell_strategy_b()

        if self.strategy_a_lot == 0 and self.spy_crossed_above:
            self._buy_strategy_a(float(bars[self.spy].Close))

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            self._buy_strategy_b(float(bars[self.aapl].Close))

    def _update_spy_state(self, close):
        previous_sma = None
        if len(self.spy_closes) >= self.SMA_PERIOD:
            previous_sma = sum(self.spy_closes) / self.SMA_PERIOD

        previous_close = self.spy_previous_close

        self.spy_closes.append(close)

        current_sma = None
        if len(self.spy_closes) >= self.SMA_PERIOD:
            current_sma = sum(self.spy_closes) / self.SMA_PERIOD

        self.spy_crossed_above = (
            previous_close is not None
            and previous_sma is not None
            and current_sma is not None
            and previous_close <= previous_sma
            and close > current_sma
        )

        self.spy_crossed_below = (
            previous_close is not None
            and previous_sma is not None
            and current_sma is not None
            and previous_close >= previous_sma
            and close < current_sma
        )

        self.spy_previous_close = close

    def _update_aapl_state(self, close):
        previous_close = self.aapl_previous_close

        if previous_close is None:
            self.aapl_red_streak = 0
        elif close < previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.aapl_previous_rsi = self.aapl_rsi

        if previous_close is not None:
            change = close - previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_change_count < self.RSI_PERIOD:
                self.rsi_gain_sum += gain
                self.rsi_loss_sum += loss
                self.rsi_change_count += 1

                if self.rsi_change_count == self.RSI_PERIOD:
                    self.rsi_average_gain = self.rsi_gain_sum / self.RSI_PERIOD
                    self.rsi_average_loss = self.rsi_loss_sum / self.RSI_PERIOD
                    self.aapl_rsi = self._calculate_rsi(
                        self.rsi_average_gain,
                        self.rsi_average_loss
                    )
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * (self.RSI_PERIOD - 1)) + gain
                ) / self.RSI_PERIOD

                self.rsi_average_loss = (
                    (self.rsi_average_loss * (self.RSI_PERIOD - 1)) + loss
                ) / self.RSI_PERIOD

                self.aapl_rsi = self._calculate_rsi(
                    self.rsi_average_gain,
                    self.rsi_average_loss
                )

        self.aapl_previous_close = close

    def _calculate_rsi(self, average_gain, average_loss):
        if average_loss == 0.0:
            return 100.0 if average_gain > 0.0 else 50.0

        relative_strength = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _buy_strategy_a(self, close):
        target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
        quantity = int(math.floor(target_value / close))

        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.spy, quantity, tag="Strategy A Buy")
        filled = int(ticket.QuantityFilled)

        if filled > 0:
            self.strategy_a_lot += filled

    def _sell_strategy_a(self):
        if self.strategy_a_lot <= 0:
            return

        ticket = self.MarketOrder(
            self.spy,
            -self.strategy_a_lot,
            tag="Strategy A Sell"
        )
        filled = abs(int(ticket.QuantityFilled))

        if filled > 0:
            self.strategy_a_lot = max(0, self.strategy_a_lot - filled)

    def _buy_strategy_b(self, close):
        if float(self.Portfolio.Cash) < self.AAPL_BUY_CASH:
            return

        quantity = int(math.floor(self.AAPL_BUY_CASH / close))

        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.aapl, quantity, tag="Strategy B Buy")
        filled = int(ticket.QuantityFilled)

        if filled > 0:
            self.strategy_b_lot += filled

    def _sell_strategy_b(self):
        if self.strategy_b_lot <= 0:
            return

        ticket = self.MarketOrder(
            self.aapl,
            -self.strategy_b_lot,
            tag="Strategy B Sell"
        )
        filled = abs(int(ticket.QuantityFilled))

        if filled > 0:
            self.strategy_b_lot = max(0, self.strategy_b_lot - filled)

