        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_orders = {}

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        spy_buy_signal = False
        spy_sell_signal = False

        if spy_bar is not None:
            spy_close = spy_bar.Close
            prior_spy_close = self.previous_spy_close
            prior_spy_sma = self.previous_spy_sma

            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == self.SMA_PERIOD:
                current_spy_sma = sum(self.spy_closes) / Decimal(self.SMA_PERIOD)

                if prior_spy_close is not None and prior_spy_sma is not None:
                    spy_buy_signal = (
                        prior_spy_close <= prior_spy_sma
                        and spy_close > current_spy_sma
                    )
                    spy_sell_signal = (
                        prior_spy_close >= prior_spy_sma
                        and spy_close < current_spy_sma
                    )

                self.previous_spy_sma = current_spy_sma

            self.previous_spy_close = spy_close

        if aapl_bar is not None:
            aapl_close = aapl_bar.Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        aapl_sell_signal = (
            self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > self.RSI_EXIT_LEVEL
        )

        if (
            self.strategy_a_lot > 0
            and not self._has_pending_order("A")
            and spy_sell_signal
        ):
            self._submit_order("A", self.spy, -self.strategy_a_lot, "A_SELL")

        if (
            self.strategy_b_lot > 0
            and not self._has_pending_order("B")
            and aapl_sell_signal
        ):
            self._submit_order("B", self.aapl, -self.strategy_b_lot, "B_SELL")

        if (
            self.strategy_a_lot == 0
            and not self._has_pending_order("A")
            and spy_buy_signal
        ):
            spy_close = data.Bars[self.spy].Close
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * self.SPY_ALLOCATION)
                / spy_close
            )

            if quantity > 0:
                self._submit_order("A", self.spy, quantity, "A_BUY")

        if (
            self.strategy_b_lot == 0
            and not self._has_pending_order("B")
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= self.AAPL_BUY_AMOUNT
        ):
            aapl_close = data.Bars[self.aapl].Close
            quantity = int(self.AAPL_BUY_AMOUNT / aapl_close)

            if quantity > 0:
                self._submit_order("B", self.aapl, quantity, "B_BUY")

    def _has_pending_order(self, strategy):
        return any(
            order_strategy == strategy
            for order_strategy, _ in self.pending_orders.values()
        )

    def _submit_order(self, strategy, symbol, quantity, tag):
        if quantity == 0:
            return

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is not None:
            action = "BUY" if quantity > 0 else "SELL"
            self.pending_orders[ticket.OrderId] = (strategy, action)

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        strategy, action = self.pending_orders[order_id]

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            fill_quantity = int(order_event.FillQuantity)

            if strategy == "A":
                if action == "BUY":
                    self.strategy_a_lot += fill_quantity
                else:
                    self.strategy_a_lot = max(
                        0,
                        self.strategy_a_lot + fill_quantity
                    )
            else:
                if action == "BUY":
                    self.strategy_b_lot += fill_quantity
                else:
                    self.strategy_b_lot = max(
                        0,
                        self.strategy_b_lot + fill_quantity
                    )

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]

