            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Closed
        ):
            self.pending_orders.pop(order_event.OrderId, None)

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return

        self.pending_orders[ticket.OrderId] = strategy + (
            "_BUY" if quantity > 0 else "_SELL"
        )

        if ticket.Status == OrderStatus.Filled:
            self.pending_orders.pop(ticket.OrderId, None)
            self._apply_fill(
                strategy + ("_BUY" if quantity > 0 else "_SELL"),
                int(quantity)
            )

    def _apply_fill(self, role, fill_quantity):
        if role == "A_BUY":
            self.strategy_a_lot += fill_quantity
        elif role == "A_SELL":
            self.strategy_a_lot = max(0, self.strategy_a_lot + fill_quantity)
        elif role == "B_BUY":
            self.strategy_b_lot += fill_quantity
        elif role == "B_SELL":
            self.strategy_b_lot = max(0, self.strategy_b_lot + fill_quantity)

    def _has_no_pending_order(self, strategy):
        return not any(
            role.startswith(strategy + "_")
            for role in self.pending_orders.values()
        )

