                            quantity,
                            "Strategy B buy"
                        )

        if present[self.spy]:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma_value
            self.previous_spy_valid = True
        else:
            self.previous_spy_valid = False

        if present[self.aapl]:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
        else:
            self.previous_aapl_close = None
            self.aapl_red_streak = 0

    def _pending_order(self, strategy):
        return self.pending_orders.get(strategy)

    def _submit_order(self, strategy, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)

        if ticket is not None:
            self.pending_orders[strategy] = {
                "order_id": ticket.OrderId,
                "side": "buy" if quantity > 0 else "sell"
            }

    def OnOrderEvent(self, order_event):
        matched_strategy = None
        order_info = None

        for strategy, info in self.pending_orders.items():
            if info["order_id"] == order_event.OrderId:
                matched_strategy = strategy
                order_info = info
                break

        if matched_strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if matched_strategy == "spy":
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            else:
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[matched_strategy]
